// V7: private photos/video live in P04 «Приватное» (s-profile.js); M01/M03 are aliases.

// Couple: an invitation never means consent or merges private accounts.
ACT.pairLink=()=>go('Q01');
/* Q01 — couple connection (owner 15.10): a real scene — your avatar, the partner's place and the link between them —
   and the partner's nickname right here (no extra screen). Typing a nickname shows who you are about to invite. */
const pairScene=(other,state)=>`<div class="pair-scene ${state}"><span class="ps-av me">${av('me','')}</span><span class="ps-link"><i></i><i></i><i></i><b>${I.couple}</b></span><span class="ps-av ot" id="psOther">${other&&PEOPLE[other]?av(other,''):`<span class="ps-q">${I.plus}</span>`}</span></div>`;
SC.Q01={title:()=>L('Связь пары','Couple connection'),render:(p,r)=>{const P=S.pair,inv=S.pairInvite;if(P?.status==='dissolved'||P?.status==='deleted')return SC.Q07.render();
 if(P?.status==='active'){coupleProfile();return `${bar(L('Пара','Couple'),{back:1,sm:1})}<div class="view nodock"><div class="wrap pair-wrap">${pairScene(P.with,'on')}<h2 class="t center">${esc(pairName())}</h2><p class="lead center">${L('Общий профиль двух отдельных аккаунтов','A shared profile of two separate accounts')}</p>${pairStatusHTML()}${jointWorkHTML()}<div class="card list">${linkRow({go:'Q03',icon:'couple',title:L('Страница пары','Couple page')})}</div>
 <div class="sec">${L('Настройки пары','Couple settings')}</div><div class="card list">${linkRow({act:'pairTrustOpen',icon:'check',title:L('Подтверждение партнёром','Partner approval'),sub:pairTrusted()?L('Не нужно — вы доверяете друг другу','Not needed — you trust each other'):P.trust?.consents?.length?L('Ждём согласия второго участника','Waiting for the other partner'):L('Нужно для каждой публикации и версии профиля','Needed for every post and profile version')})}${linkRow({go:'Q05',icon:'key',title:L('Доступы пары','Couple access')})}${pairSafetyRows()}</div>
 <div class="sec">${L('Осторожно','Careful')}</div><div class="card list">${linkRow({go:'Q06',cls:'danger',icon:'x',title:L('Разъединить пару','Unlink couple')})}</div></div></div>`;}
 if(inv)return `${bar(L('Пара','Couple'),{back:1,sm:1})}<div class="view nodock"><div class="wrap pair-wrap">${pairScene(inv.nick,'wait')}<h2 class="t center">${L('Ждём ответа','Waiting for an answer')}</h2><p class="lead center">${L(`Приглашение у ${esc(PEOPLE[inv.nick]?pname(inv.nick):'@'+inv.nick)}. Пара появится, когда человек подтвердит в своём аккаунте.`,`The invitation is with ${esc(PEOPLE[inv.nick]?pname(inv.nick):'@'+inv.nick)}. The couple appears once they confirm in their own account.`)}</p><button class="btn soft mt12" data-act="v6PairCancel">${L('Отозвать приглашение','Withdraw invitation')}</button></div></div>`;
 return `${bar(L('Пара','Couple'),{back:1,sm:1})}<div class="view nodock cta1"><div class="wrap pair-wrap">${pairScene(null,'')}
 <h2 class="t center">${L('Вместе — по взаимному решению','Together, by mutual agreement')}</h2>
 <div class="pair-facts">${[[I.couple,L('Общий профиль пары','A shared couple profile'),L('Фото, описание и интересы пары','Photos, description and interests of the couple')],[I.lock,L('Личное остаётся личным','Personal stays personal'),L('Свои аккаунты, чаты и интересы','Your own accounts, chats and interests')],[I.check,L('Только с согласия обоих','Only if both agree'),L('Каждый подтверждает у себя','Each confirms in their own account')]].map(([i,b,t])=>`<div class="pf"><span class="ico v">${i}</span><span><b>${b}</b><small>${t}</small></span></div>`).join('')}</div>
 ${field({name:'partner',label:L('Ник партнёра','Partner’s nickname'),icon:'at',ph:'nickname',attrs:'autocapitalize="off" spellcheck="false" autocomplete="off" data-enter="v6PairInvite"'})}
 <div class="pair-prev" id="pairPrev"></div>
 </div></div><div class="ctabar"><div class="wrap"><button class="btn primary" data-act="v6PairInvite">${I.send}${L('Пригласить в пару','Invite to couple')}</button></div></div>`;},
 after:()=>{const f=$('[name="partner"]');if(!f)return;const upd=()=>{const n=f.value.trim().replace(/^@/,'').toLowerCase();const ok=PEOPLE[n]&&!PEOPLE[n].pair&&n!==S.me.nick;const o=$('#psOther'),pv=$('#pairPrev');if(o)o.innerHTML=ok?av(n,''):`<span class="ps-q">${I.plus}</span>`;$('.pair-scene')?.classList.toggle('ready',!!ok);if(pv)pv.innerHTML=ok?`<div class="li static">${av(n,'sm')}<span class="tx"><b>${esc(pname(n))}${nameBadges(PEOPLE[n])}</b><small>${esc(whoLine(n))}</small></span><span class="pill ok">${I.check}${L('найден','found')}</span></div>`:n.length>2?`<p class="note">${L('Пока не нашли такой ник — проверь написание','No such nickname yet — check the spelling')}</p>`:'';};f.addEventListener('input',upd);upd();}};
SC.Q02={...SC.Q01};
ACT.v6PairInvite=a=>{if(activePair()||S.pair?.status==='dissolved')return;const ticket=authorTicket('me'),r=cur(),nick=fv('partner').trim().replace(/^@/,'');if(!/^[a-z0-9_.]{3,20}$/i.test(nick)||nick===S.me.nick||!PEOPLE[nick]||PEOPLE[nick].pair||PEOPLE[nick].pairOf){setErr('partner',L('Укажи другой корректный ник','Enter another valid nickname'));return;}run(a,()=>{if(!validAuthor(ticket)||cur()!==r||activePair()||S.pairInvite?.status==='pending')return;S.pairInvite={nick,status:'pending',by:'me',t:Date.now()};autoResolve();r.dirty=false;go('Q01',{}, {replace:true});},{ok:L('Приглашение отправлено','Invitation sent')});};
ACT.v6PairCancel=()=>{S.pairInvite=null;refresh();};
/* Q03 — the couple profile: a layer over two separate accounts. Each person keeps own chats, likes and grants. */
const pairName=()=>S.pair?T(S.pair.name):'';
/* Immediate safety actions show their outcome; completed states are text, not dead navigation. */
function pairSafetyRows(){const P=coupleProfile(),d=social('couple');if(!P||!d)return '';
 const datingOff=!P.dating&&!P.datingVisible;
 const privateOff=P.requestsFrom==='none'&&!d.sharedByMe.some(g=>g.scopes?.length&&grantTimeActive(g.until))&&!d.reqIn.some(g=>['open','partial','granted'].includes(effectiveRequestStatus(g))&&g.granted?.length)&&!(S.pair.grants||[]).length;
 const row=(off,act,icon,title,done,sub,doneSub)=>off?`<div class="li static"><span class="ico">${I[icon]}</span><span class="tx"><b>${done}</b><small>${doneSub}</small></span><span class="ico g" aria-hidden="true">${I.check}</span></div>`:linkRow({act,icon,title,sub,noChev:1});
 return row(datingOff,'pairHide','eyeoff',L('Скрыть из знакомств','Hide from Discover'),L('Пара скрыта из знакомств','Couple hidden from Discover'),L('Сразу выключить показ пары в подборке','Turn off the couple’s visibility immediately'),L('Показ в подборке выключен','Discover visibility is off'))+row(privateOff,'pairStopSharing','lock',L('Закрыть приватную часть','Close private part'),L('Приватная часть закрыта','Private part closed'),L('Отозвать все доступы и выключить запросы','Revoke all access and turn off requests'),L('Доступов нет, новые запросы выключены','No shared access; new requests are off'));
}
/* pair page = profile only (owner 19.10); everything the pair manages lives in one hub: Q01 */
function pairStatusHTML(){const P=S.pair,q=P.proposal;coupleProfile();
 const profilePending=q?.status==='pending',changed=P.draft&&coupleDraftChanged();
 const status=profilePending?grp(L('Изменения профиля','Profile changes'),`<button class="li" data-act="pairReview"><span class="ico">${I.clock}</span><span class="tx"><b>${q.by===pairMember()?L('Ждём согласия партнёра','Waiting for your partner'):L('Партнёр предлагает изменения','Your partner proposed changes')}</b><small>${esc(pname(q.by))}</small></span>${I.chev}</button>`,{list:1}):changed?grp(L('Черновик профиля','Profile draft'),`<p class="note">${L('Изменения ещё не видны другим','Changes are not visible to others yet')}</p>${P.draftBy&&P.draftBy!==pairMember()?`<button class="btn soft" data-act="pairClaimDraft">${L('Продолжить общий черновик','Continue the shared draft')}</button>`:`<button class="btn primary" data-act="pairSubmit">${pairTrusted()?L('Опубликовать изменения','Publish changes'):L('Отправить на согласование','Request approval')}</button>`}`):'';
 return status;}
SC.Q03={title:()=>L('Профиль пары','Couple profile'),valid:()=>activePair(),render:(p,r)=>{coupleProfile();return profileView('couple',r,{});},after:()=>fillJars()};
ACT.pairSubmit=()=>{if(submitCoupleDraft())refresh();};
ACT.pairViewAs=()=>{S.pairMember=S.pairMember==='partner'?'me':'partner';refresh();};
ACT.pairReview=()=>{const P=S.pair,q=P?.proposal;if(!q)return;const next=normalizedCouple(q.text),prev=normalizedCouple(P.profile);const keys=Object.keys(next).filter(k=>JSON.stringify(next[k])!==JSON.stringify(prev[k]));const labels={privOn:L('Приватная часть','Private part'),privText:L('Приватное описание','Private description'),city:L('Город','City'),pron:L('Обращение','Pronouns'),gender:L('Гендер','Gender'),orient:L('Ориентация','Orientation'),role:L('Роли','Roles'),format:L('Формат отношений','Relationship format'),seek:L('Что ищем','Looking for'),status:L('Статус','Status'),showAge:L('Показ возраста','Age visibility'),history:L('История интересов','Interest history'),nick:L('Имя профиля','Profile name'),name:L('Название','Name'),bio:L('Описание','About'),photos:L('Фото','Photos'),photo:L('Главное фото','Main photo'),jars:L('Интересы','Interests'),media:L('Приватные материалы','Private media'),vis:L('Видимость полей','Field visibility'),dating:L('Знакомства','Dating'),datingVisible:L('Показ в подборке','Discover visibility'),socialLikes:L('Симпатии из профиля','Profile likes'),requestsFrom:L('Запросы доступа','Access requests')};sheet(()=>({title:L('Предложенная версия','Proposed version'),body:`<div class="pair-review-meta">${esc(pname(q.by))}<span class="pill">${L('Изменения профиля','Profile changes')}</span></div><div class="review-changes">${keys.map(k=>`<div class="li static"><span class="tx"><b>${esc(labels[k]||L('Поле профиля','Profile field'))}</b><small>${['name','bio','privText'].includes(k)?esc(T(q.text[k])):Array.isArray(q.text[k])?String(q.text[k].length):typeof q.text[k]==='boolean'?(q.text[k]?L('Включено','On'):L('Выключено','Off')):k==='requestsFrom'?({all:L('Все','Everyone'),matches:L('Взаимные симпатии','Mutual likes'),none:L('Никто','Nobody')}[q.text[k]]||esc(q.text[k])):typeof q.text[k]==='string'?esc(q.text[k]):L('Изменено — см. итоговый профиль','Changed — see resulting profile')}</small></span>${I.check}</div>`).join('')}</div><button class="btn soft mt12" data-go="P03" data-p='${esc(JSON.stringify({owner:'couple',preview:q.text}))}'>${L('Итоговый профиль','Resulting profile')}</button>`,foot:q.by!==pairMember()?`<button class="btn primary" data-act="pairProposal" data-v="yes" data-version="${q.id}">${L('Одобрить всю версию','Approve complete version')}</button><button class="btn soft mt8" data-act="pairProposal" data-v="no" data-version="${q.id}">${L('Вернуть на доработку','Return for changes')}</button>`:`<p class="note">${L('Одобрить может только другой участник','Only the other partner can approve')}</p>`}));};
ACT.pairProposal=a=>{const P=S.pair,q=P?.proposal,t=authorTicket('couple');if(!q||q.by===pairMember()||a.dataset.version&&a.dataset.version!==q.id)return;run(a,()=>{if(!validAuthor(t)||P.proposal!==q)return;if(a.dataset.v==='yes')commitCoupleProposal(P,pairMember(),q.id);else{q.status='returned';P.draft??=structuredClone(q.text);pairNotify('returned',q.id,{go:['Q01']});}closeSheet();refresh();},{ms:300});};
ACT.pairClaimDraft=()=>{const P=S.pair;if(!activePair()||P.proposal?.status==='pending')return;P.draftBy=pairMember();P.draftLease=(P.draftLease||0)+1;refresh();};
function pairSafety(kind){const P=S.pair;if(!activePair())return;coupleProfile();P.safetyEpoch=(P.safetyEpoch||0)+1;if(kind==='dating'){P.profile.dating=false;P.profile.datingVisible=false;if(P.draft){P.draft.dating=false;P.draft.datingVisible=false;}}else{const d=social('couple');d.sharedByMe=[];d.reqIn.forEach(x=>{x.status='no';x.granted=[];});P.grants=[];P.profile.requestsFrom='none';if(P.draft)P.draft.requestsFrom='none';}P.proposal=null;P.revision=(P.revision||0)+1;P.draftBase=P.revision;markCoupleDraft();refresh();toast(kind==='dating'?L('Пара скрыта из знакомств','Couple hidden from Discover'):L('Доступы отозваны. Новые запросы выключены.','Access revoked. New requests are off.'),{type:'ok'});}
ACT.pairHide=()=>pairSafety('dating');ACT.pairStopSharing=()=>pairSafety('sharing');
SC.Q04={...SC.P02,render:(p,r)=>{r.p.owner='couple';return SC.P02.render(r.p,r);}};
