SC.Q06={title:()=>L('Разъединить пару','Unlink couple'),render:()=>{const row=(ic,tone,t,sub)=>`<div class="li static"><span class="ico ${tone}">${ic}</span><span class="tx"><b>${t}</b><small>${sub}</small></span></div>`;
 return `${bar(L('Разъединить пару','Unlink couple'),{back:1,sm:1})}<div class="view nodock"><div class="wrap"><p class="lead">${L('Каждый остаётся со своим аккаунтом. Вот что изменится.','Each of you keeps your own account. Here is what changes.')}</p>
 <div class="sec">${L('Останется','Stays')}</div><div class="card list">${row(I.me,'g',L('Личные аккаунты','Personal accounts'),L('Профили, посты, чаты, подписки и интересы — у каждого свои','Profiles, posts, chats, follows and interests stay with each of you'))}${row(I.doc,'g',L('Совместные публикации','Joint posts'),L('Остаются в закрытом архиве с именами обоих, но без новых действий','Kept in a private archive with both names, no new actions'))}</div>
 <div class="sec">${L('Закроется','Stops')}</div><div class="card list">${row(I.couple,'a',L('Страница пары и анкета знакомств','Couple page and dating profile'),L('Пропадут из подборки и поиска','Removed from Discover and search'))}${row(I.lock,'a',L('Общие доступы к приватной части','Shared private-part grants'),L('Отзываются сразу','Revoked at once'))}${row(I.chat,'a',L('Парные чаты','Couple chats'),L('Остаются только на чтение у обоих','Read-only for both'))}</div>
 <p class="note mt12">${L('Вернуть пару можно в течение 30 дней, если оба подтвердят.','You can restore the couple within 30 days if both of you confirm.')}</p>
 <button class="btn danger mt12" data-act="v6PairUnlink">${L('Разъединить','Unlink')}</button></div></div>`;}};
ACT.v6PairUnlink=()=>{const P=S.pair,session=S.session;ask({title:L('Разъединить пару?','Unlink the couple?'),text:L('Общий профиль отключится сразу. Восстановление возможно 30 дней с согласия обоих.','The couple profile stops immediately. Both partners may restore it within 30 days.'),ok:L('Разъединить','Unlink'),danger:true}).then(ok=>{if(ok&&S.pair===P&&S.session===session){dissolvePair();go('Q07',{}, {replace:true});}});};
SC.Q07={title:()=>L('Связь остановлена','Connection stopped'),render:()=>{expirePair();const P=S.pair;return `${bar(L('Связь остановлена','Connection stopped'),{back:1,sm:1})}<div class="view nodock"><div class="wrap"><h2>${L('Личные аккаунты продолжают работать','Personal accounts keep working')}</h2><p class="lead">${P?.status==='deleted'?L('Срок восстановления истёк. Данные совместного профиля удалены из модели прототипа.','The recovery period ended. Couple data has been removed from the prototype model.'):L('Совместный профиль скрыт. Новые действия и сообщения недоступны, приватные разрешения прекращены. Восстановление — в течение 30 дней, по согласию обоих.','The couple profile is hidden. New actions and messages stop, private permissions are revoked. Both partners can restore it within 30 days.')}</p>${P?.status==='dissolved'?`<p class="note">${L('Согласий на восстановление','Recovery approvals')}: ${P.recovery.length}/2</p><button class="btn primary" data-act="pairRestore">${L('Согласиться на восстановление','Agree to restore')}</button>`:''}${P?`<button class="btn soft" data-go="Q08">${L('Совместный архив','Joint archive')}</button>`:''}<button class="btn text" data-go="X01">${L('К личному аккаунту','My personal account')}</button></div></div>`;}};
