ACT.pairInvitationReview=()=>{const inv=S.pairInvite;if(!inv||inv.status!=='pending')return;S.pairMember='partner';sheet(()=>({title:L('Приглашение в пару','Couple invitation'),body:`<p class="lead">${esc(pname('me'))} ${L('предлагает создать совместный профиль с','wants to create a couple profile with')} ${esc(pname(inv.nick))}.</p>`,foot:`<button class="btn primary" data-act="pairInvitationAnswer" data-v="yes">${L('Принять','Accept')}</button><button class="btn soft mt8" data-act="pairInvitationAnswer" data-v="no">${L('Отклонить','Decline')}</button>`}));};
function acceptPairInvitation(reviewer=pairMember()){const inv=S.pairInvite;if(!inv||reviewer!==inv.nick||inv.by===reviewer||inv.status!=='pending'||activePair()||!PEOPLE[inv.nick]||PEOPLE[inv.nick].pairOf)return false;startPair(inv.nick);S.pairInvite=null;return true;}
function startPair(nick){S.pair={id:'pair_'+nick+'_'+Date.now(),status:'active',with:nick,since:Date.now(),name:{ru:`${pname('me')} и ${pname(nick)}`,en:`${pname('me')} & ${pname(nick)}`},desc:{ru:'',en:''},rules:{ru:'',en:''},proposal:null,grants:[],revision:0};coupleProfile();}
/* an invitation FROM someone to me: answered in the decisions inbox */
ACT.pairIncomingAnswer=a=>{const inv=S.pairIncoming,owner=S,session=S.session;if(!inv||inv.status!=='pending'||activePair()||!PEOPLE[inv.from]||PEOPLE[inv.from].pairOf||isBlocked(inv.from))return;run(a,()=>{if(S!==owner||S.session!==session||S.pairIncoming!==inv||activePair())return;if(a.dataset.v==='yes'){inv.status='accepted';startPair(inv.from);refresh();go('Q01');}else{inv.status='declined';refresh();}},{ok:a.dataset.v==='yes'?L('Вы теперь пара. Личные аккаунты остаются отдельными','You’re a couple now. Personal accounts stay separate'):L('Приглашение отклонено','Invitation declined')});};
ACT.pairInvitationAnswer=a=>{if(S.pairMember!=='partner')return;if(a.dataset.v==='yes')acceptPairInvitation();else S.pairInvite=null;S.pairMember='me';closeSheet();activePair()?go('Q01'):refresh();};

// Community management never grants personal chat access.
SC.C11={title:()=>L('Заявки сообщества','Community requests'),valid:p=>ownsCommunity(p.id),render:p=>{if(!ownsCommunity(p.id))return unavailable();const all=S.communityRequests[p.id]||[],pending=all.filter(x=>x.status==='pending'),done=all.filter(x=>x.status!=='pending');const t=p.t==='history'?'history':'pending',list=t==='history'?done:pending;
 return `${bar(L('Заявки сообщества','Community requests'),{back:1,sm:1,sub:esc(T(COMMUNITIES[p.id].name))})}<div class="view nodock"><div class="wrap">${seg([['pending',L('Новые','New'),pending.length||''],['history',L('Решения','Decisions'),done.length||'']],t,'cRequestsTab')}
 <p class="note mt12">${L('Ответы видны только ведущим. Одобрение даёт участие в сообществе, но не открывает личный чат или приватную часть.','Only hosts can see the answers. Approval grants community membership, never a private chat or private part.')}</p>
 ${list.map(req=>`<section class="card mt12">${personRow(req.p)}<p class="note">${F.rel(req.updated||req.t)}${req.status!=='pending'?' · '+({approved:L('Одобрено','Approved'),declined:L('Отклонено','Declined'),withdrawn:L('Отозвана','Withdrawn')}[req.status]||''):''}</p><p style="white-space:pre-wrap">${esc(T(req.answer))}</p>${req.status==='pending'?`<div class="row g8"><button class="btn soft" data-act="cRequestDecision" data-v="${esc(req.id)}" data-status="declined">${L('Отклонить','Decline')}</button><button class="btn primary" data-act="cRequestDecision" data-v="${esc(req.id)}" data-status="approved">${L('Одобрить','Approve')}</button></div>`:''}</section>`).join('')||empty('doc',t==='history'?L('Решений пока нет','No decisions yet'):L('Новых заявок нет','No new requests'),L('Ответы участников видны только ведущим этого сообщества.','Applicant answers are visible only to this community’s hosts.'))}</div></div>`;}};
ACT.cRequestsTab=a=>setP('t',a.dataset.v);
ACT.cRequestDecision=a=>{const owner=S,session=S.session,route=cur(),id=a.dataset.c||route.p.id,status=a.dataset.status,req=(S.communityRequests[id]||[]).find(x=>x.id===a.dataset.v),community=COMMUNITIES[id],applicant=req?.p,reviewedAnswer=JSON.stringify(req?.answer);
 const allowed=()=>S===owner&&S.session===session&&cur()===route&&(route.id==='C11'||route.id==='N01'&&a.dataset.c===id)&&ownsCommunity(id)&&COMMUNITIES[id]===community&&community.status!=='review'&&(S.communityRequests[id]||[]).includes(req)&&req?.status==='pending'&&req.p===applicant&&JSON.stringify(req.answer)===reviewedAnswer&&req.p!=='me'&&!!PEOPLE[req.p];
 if(!['approved','declined'].includes(status)||!allowed())return;const submit=()=>{if(!allowed())return;let changed=false;return run(status==='approved'?a:null,()=>{if(!allowed())return;req.status=status;req.updated=Date.now();if(status==='approved'&&!(community.seedMembers||[]).includes(req.p))(S.communityMembers[id]??=new Set()).add(req.p);changed=true;refresh();},{ok:()=>changed?(status==='approved'?L('Участие одобрено','Membership approved'):L('Заявка отклонена','Request declined')):null});};
 if(status==='declined')return ask({title:L('Отклонить заявку?','Decline this request?'),text:L('Участие в сообществе не откроется. Это не блокировка профиля.','Community membership will not be granted. This does not block the profile.'),ok:L('Отклонить','Decline'),danger:true}).then(ok=>ok?submit():undefined);return submit();};
SC.C12={title:()=>L('Модерация сообщества','Community moderation'),valid:p=>ownsCommunity(p.id),render:p=>!ownsCommunity(p.id)?unavailable():`${bar(L('Модерация сообщества','Community moderation'),{back:1,sm:1})}<div class="view nodock"><div class="wrap">${empty('shield',L('Очередь обращений пуста','Report queue is empty'),L('Проверяй обсуждения, ответы и правила. Личные данные участников ведущим недоступны.','Review discussions, replies and rules. Hosts cannot access members’ private data.'))}${linkRow({go:'C03',p:{id:p.id,t:'rules'},icon:'doc',title:L('Правила сообщества','Community rules')})}</div></div>`};
const manageCommunity=SC.C10.render;SC.C10.render=(p,r)=>manageCommunity(p,r).replace('data-act="soon"','data-go="C11" data-id="'+p.id+'"').replace('data-act="soon"','data-go="C12" data-id="'+p.id+'"').replace('data-act="soon"','data-act="v6CommunityEdit"').replace('data-act="soon"','data-act="v6Hosts"');
ACT.v6CommunityEdit=()=>{if(!ownsCommunity(cur().p.id))return;const c=COMMUNITIES[cur().p.id];S.ui.communityDraft={name:T(c.name),desc:T(c.desc),rules:c.rules.map(T).join('\n')};sheet(()=>({title:L('Описание и правила','Description and rules'),body:`<label class="field"><span>${L('Название','Name')}</span><input class="inp" id="v6cn" value="${esc(S.ui.communityDraft.name)}"></label>${rteField({name:'v6cd',local:'v6cd',value:S.ui.communityDraft.desc,label:L('Описание','Description'),max:500})}<label class="field"><span>${L('Правила — по одному на строку','Rules — one per line')}</span><textarea class="inp" id="v6cr">${esc(S.ui.communityDraft.rules)}</textarea></label>`,foot:`<button class="btn primary" data-act="v6CommunitySave">${L('Сохранить','Save')}</button>`}));};
ACT.v6CommunitySave=()=>{if(!ownsCommunity(cur().p.id))return;const c=COMMUNITIES[cur().p.id],name=$('#v6cn').value.trim(),desc=rteVal('v6cd').trim(),rules=$('#v6cr').value.trim();if(name.length<3||!rules){toast(L('Нужны название и правила','A name and rules are required'),{type:'err'});return;}c.name={ru:name,en:name};c.desc={ru:desc,en:desc};c.rules=rules.split('\n').map(x=>({ru:x,en:x}));closeSheet();refresh();};
ACT.v6Hosts=()=>ownsCommunity(cur().p.id)&&sheet(()=>({title:L('Ведущие сообщества','Community hosts'),body:`<div class="card list">${communityHostIds(cur().p.id).map(id=>personRow(id)).join('')||personRow('me')}</div><p class="note">${L('Назначение ролей требует отдельной проверки прав. Роль ведущего не открывает личные профили участников.','Assigning roles needs a separate permission check. A host role never opens members’ private parts.')}</p>`}));

SC.K08={title:()=>L('Ссылки и сравнения','Links and comparisons'),render:()=>`${bar(L('Ссылки и сравнения','Links and comparisons'),{back:1,sm:1})}<div class="view nodock compact"><div class="wrap">${empty('link',L('Активных приватных ссылок нет','No active private links'),L('Публичная ссылка не передаёт доступ. Приватные ссылки должны иметь выбранные разделы, срок и отзыв.','A public link never transfers access. Private links need selected sections, expiry and revocation.'))}<button class="btn soft" data-act="shareProfile">${L('Поделиться публичным профилем','Share public profile')}</button></div></div>`};
const settingsRender=SC.K01.render;SC.K01.render=(...a)=>settingsRender(...a).replace('<div class="sec">'+L('Поддержка','Support')+'</div>',`<div class="card list">${linkRow({go:'K08',icon:'link',title:L('Ссылки и сравнения','Links and comparisons')})}</div><div class="sec">${L('Поддержка','Support')}</div>`);
const helpText=()=>({shield:[L('Подтверждение возраста','Age verification'),L('Дата рождения — самодекларация. Отдельная проверка даёт доступ к ограниченным функциям и не публикует документы.','Date of birth is self-declared. Separate verification enables restricted features and never publishes documents.')],lock:[L('Кто видит личное','Who sees private details'),L('Только выбранный человек, выбранные разделы и только на указанный срок. Доступ можно отозвать бесплатно.','Only the selected person sees the selected sections for the chosen duration. Revocation is free.')],heart:[L('Личные чаты','Private conversations'),L('Чат открывает взаимная личная симпатия. Подписка, посты, участие и приватный доступ не дают права написать.','Only mutual personal likes open a chat. Following, posts, attendance and private grants never enable messaging.')],cal:[L('Офлайн-встречи','In-person meetings'),L('Проверь организатора, условия, время и способы связи. Сообщи близкому план встречи. При непосредственной опасности обратись в местную экстренную службу.','Check the organiser, requirements, time and contact details. Tell someone you trust your plan. In immediate danger, contact your local emergency service.')],crown:[L('Подписка','Membership'),L('Premium увеличивает квоты и историю. Приватность, отказ, отзыв и ответная симпатия бесплатны. Покупка не даёт чужого согласия.','Premium expands quotas and history. Privacy, refusal, revocation and liking back are free. Purchasing never buys consent.') ]});
const helpRender=SC.S01.render;SC.S01.render=(...a)=>{let html=helpRender(...a);for(const key of ['shield','lock','heart','cal','crown'])html=html.replace('data-act="soon"',`data-act="v6Help" data-v="${key}"`);return html.replace(L('При опасности звони 112.','In danger, call 112.'),L('При опасности обратись в местную экстренную службу.','In danger, contact your local emergency service.'));};
ACT.v6Help=a=>{const [title,text]=helpText()[a.dataset.v];sheet(()=>({title,body:`<p class="lead">${text}</p>`}));};

// Hash links update in place. Copy links are real; no sensitive form input enters URLs.
const renderV6=render;render=function(dir,keep){renderV6(dir,keep);const r=cur();const hash=r.id+(r.p.id?':'+encodeURIComponent(r.p.id):'');history.replaceState(history.state,'','#'+hash);};

ACT.sharePost=a=>copyReviewLink('F05',{id:a?.dataset?.v||cur().p.id});




function jointWorkHTML(){const pending=Object.values(jointQueue()).filter(q=>['pending','returned'].includes(q.status));return pending.length?grp(L('Ждёт подтверждения','Waiting for approval'),pending.map(q=>`<button class="li" data-act="jointReview" data-v="${esc(q.id)}"><span class="ico">${I.clock}</span><span class="tx"><b>${q.kind==='grant'?L('Приватный доступ','Private access'):esc(q.draft.text).slice(0,70)||L('Совместная публикация','Joint post')}</b><small>${esc(pname(q.by))} · ${L('Версия','Version')} ${q.version}${q.status==='returned'?' · '+L('На доработке','Changes requested'):''}</small></span>${I.chev}</button>`).join(''),{list:1}):'';}
function jointPostReview(d){const p=postFromDraft(d,'joint-preview');const content=postMediaHTML(p,{preview:1}).replace(/ data-(act|go|p|v|id)=("[^"]*"|'[^']*')/g,'').replace(/<button /g,'<button disabled tabindex="-1" ');
 return `<article class="joint-review-post"><div class="review-byline">${av('couple','sm')}<div><b>${esc(pname('couple'))}</b><small>${d.aud==='followers'?L('Подписчикам','Followers'):L('Всем участникам','All members')}</small></div></div><div class="body">${md(d.text)}${content}</div>${d.tags?.length?`<div class="tags">${d.tags.map(t=>`<span>#${esc(topic(t))}</span>`).join('')}</div>`:''}</article>`;
}
ACT.jointReview=a=>{const q=jointQueue()[a.dataset.v];if(!activePair()||!q||!['pending','returned'].includes(q.status))return;const version=q.version,mine=q.by===pairMember(),returned=q.status==='returned';sheet(()=>({title:q.kind==='grant'?L('Согласование доступа','Approve access'):L('Согласование публикации','Post approval'),body:`<div class="pair-review-meta">${esc(pname(q.by))}<span class="pill">${L('Версия','Version')} ${version}</span></div>${q.kind==='grant'?`<div class="joint-review-post"><p>${esc(SCOPE_TXT(q.scopes))}</p><p class="note">${q.viewers.map(x=>esc(pname(x))).join(', ')}</p></div>`:jointPostReview(q.draft)}`,foot:`<div class="review-foot">${!mine&&!returned?`<button class="btn primary" data-act="jointApprove" data-v="${esc(q.id)}" data-version="${version}">${L('Одобрить','Approve')}</button><button class="btn soft" data-act="jointReturn" data-v="${esc(q.id)}" data-version="${version}">${L('Вернуть на доработку','Request changes')}</button>`:`<p>${returned?L('Партнёр попросил внести изменения','Your partner requested changes'):L('Публикация появится после согласия партнёра','The post will appear after your partner approves')}</p>${q.kind==='post'&&mine?`<button class="btn soft" data-act="jointEdit" data-v="${esc(q.id)}">${L('Изменить публикацию','Edit post')}</button>`:''}`}</div>`}));};
ACT.jointApprove=a=>{const ticket=authorTicket('couple'),id=a.dataset.v,version=a.dataset.version,reviewer=pairMember();run(a,()=>{if(!validAuthor(ticket))return;if(approveJointWork(id,version,reviewer)){closeSheet();refresh();}else toast(L('Версия изменилась. Открой её заново','The version changed. Reopen it'),{type:'warn'});},{ms:300});};
ACT.jointReturn=a=>{const q=jointQueue()[a.dataset.v];if(!activePair()||!q||q.status!=='pending'||q.by===pairMember()||q.version!==Number(a.dataset.version))return;q.status='returned';pairNotify('workReturned',q.id+'_'+q.version,{go:['Q01']});closeSheet();refresh();};
ACT.jointEdit=a=>{const q=jointQueue()[a.dataset.v];if(!activePair()||!q||q.kind!=='post'||q.by!==pairMember())return;const d=structuredClone(q.draft);q.status='superseded';S.postEdits[q.id]={draft:d,t:Date.now()};if(!S.myPosts.some(p=>p.id===q.id))S.myPosts.unshift({...postFromDraft(d,q.id),status:'draft'});closeSheet(true);go('F07',{id:q.id,author:'couple'});};
ACT.meetPair=a=>{if(!PEOPLE[a.dataset.v]?.pair||!PEOPLE[a.dataset.v].dating)return;S.ui.datingCandidate=a.dataset.v;tab('people');};


SC.Q08={title:()=>L('Совместный архив','Joint archive'),valid:()=>!!S.session&&!!S.pair&&['dissolved','deleted'].includes(S.pair.status)&&realMembers('couple').includes(pairMember()),render:()=>{const posts=S.myPosts.filter(p=>p.author==='couple');return `${bar(L('Совместный архив','Joint archive'),{back:1,sm:1})}<div class="view"><div class="wrap"><p class="note">${L('История закрыта от других. Новые публикации и сообщения недоступны; приватные медиа отозваны.','This history is private. New posts and messages are disabled; private media access is revoked.')}</p>${posts.length?`<div class="posts">${posts.map(p=>postCard({...p,media:[],result:null,comments:[]},{detail:1,preview:1})).join('')}</div>`:empty('feed',L('Совместных публикаций пока нет','No joint posts yet'),'')}${Object.entries(S.pair.social?.threads||{}).filter(([id])=>chatReadable(id,'couple')).map(([id])=>`<button class="li" data-act="openChat" data-v="${id}" data-actor="couple">${av(id,'sm')}<span class="tx"><b>${esc(pname(id))}</b><small>${L('Архив диалога','Conversation archive')}</small></span>${I.chev}</button>`).join('')}</div></div>`;}};

let trustConsentForm=null;
ACT.pairTrustOpen=()=>{if(!authorAllowed('couple'))return;const P=S.pair;coupleProfile();const form=trustConsentForm={id:'trust_'+Date.now()+'_'+Math.random().toString(36).slice(2),ticket:authorTicket('couple')};const mine=P.trust?.consents?.includes(pairMember());sheet(()=>({title:L('Согласование','Approval'),body:`<p class="trust-copy">${L('Можно разрешить друг другу публиковать совместные посты и изменять профиль пары без каждого подтверждения. Режим включится, когда согласятся оба.','Allow each other to publish shared posts and change the couple profile without approving every change. Both partners must agree.')}</p><div>${realMembers('couple').map(id=>`<div class="trust-status"><b>${esc(pname(id))}</b><span>${P.trust?.consents?.includes(id)?L('Согласен','Agreed'):L('Не подтверждено','Not confirmed')}</span></div>`).join('')}</div><p class="trust-copy note">${L('Приватные доступы всегда согласовываются отдельно. Любой из вас может вернуть обязательное согласование.','Private access always requires separate approval. Either partner can restore approval requirements.')}</p>`,foot:`<div class="review-foot"><button class="btn ${mine?'soft':'primary'}" data-act="pairTrustSet" data-form="${esc(form.id)}" data-v="${mine?'off':'on'}" data-pair="${esc(P.id)}" data-epoch="${P.safetyEpoch||0}">${mine?L('Вернуть обязательное согласование','Require approval again'):L('Разрешить без согласования','Allow without approval')}</button></div>`}));};
ACT.pairTrustSet=a=>{const P=S.pair,form=trustConsentForm;if(!form||a.dataset.form!==form.id||!validAuthor(form.ticket))return;if(!P||a.dataset.pair!==P.id||Number(a.dataset.epoch)!==(P.safetyEpoch||0)||!authorAllowed('couple'))return;if(setPairTrust(a.dataset.v==='on')){trustConsentForm=null;closeSheet();refresh();}};
